<?php namespace App\Domains\Comercial\LiveSales\Actions; use App\Domains\Comercial\LiveSales\Services\LiveSalesService; use App\Models\InteraccionLive; use App\Models\SesionLive; class RegistrarInteraccionLiveAction{ public function __construct(private readonly LiveSalesService $service){} public function execute(SesionLive $sesion,array $data):InteraccionLive{ $this->service->validarSesionParaInteraccion($sesion); return InteraccionLive::create($data);} }
